import React from 'react';
import { motion } from 'framer-motion';
import { GripVertical, Trash2 } from 'lucide-react';
import '../styles/leads.css';

const columns = [
  { key: 'new', label: 'Mới', color: '#38bdf8' },
  { key: 'processing', label: 'Đang xử lý', color: '#facc15' },
  { key: 'converted', label: 'Chuyển đổi', color: '#4ade80' },
  { key: 'lost', label: 'Mất', color: '#f87171' },
];

const LeadKanban = ({ leads, onUpdate, onDelete }) => {
  const handleDragStart = (e, lead) => {
    e.dataTransfer.setData('lead', JSON.stringify(lead));
  };

  const handleDrop = async (e, newStatus) => {
  e.preventDefault();

  try {
    const leadId = e.dataTransfer.getData("leadId");
    if (!leadId) return;

    // Gửi PUT request cập nhật trạng thái lead
    const response = await fetch(`http://localhost:5000/api/leads/${leadId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status: newStatus }),
    });

    if (!response.ok) throw new Error("Cập nhật thất bại");
    const updatedLead = await response.json();

    // Cập nhật lại state tại frontend
    const updatedLeads = leads.map((l) =>
      l._id === updatedLead._id ? updatedLead : l
    );

    if (typeof onUpdate === "function") {
      onUpdate(updatedLeads);
    }
  } catch (err) {
    console.error("❌ Lỗi khi cập nhật lead:", err);
    alert("Không thể cập nhật trạng thái lead!");
  }
};



  return (
    <div className="kanban-container">
      {columns.map(col => (
        <div
          key={col.key}
          className="kanban-column"
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => handleDrop(e, col.key)}
        >
          <div className="kanban-header" style={{ borderBottom: `3px solid ${col.color}` }}>
            <h3>{col.label}</h3>
            <span className="lead-count">
              {leads.filter(l => l.status === col.key).length}
            </span>
          </div>

          <div className="kanban-list">
            {leads.filter(l => l.status === col.key).map(lead => (
              <motion.div
                key={lead._id}
                className="kanban-card"
                draggable
                onDragStart={(e) => handleDragStart(e, lead)}
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.98 }}
              >
                <div className="kanban-card-header">
                  <h4>{lead.name}</h4>
                  <button className="delete-btn" onClick={() => onDelete(lead._id)}>
                    <Trash2 size={16} />
                  </button>
                </div>
                <p>{lead.email}</p>
                <p>{lead.phone}</p>
                {lead.notes && <p className="notes">📝 {lead.notes}</p>}
              </motion.div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default LeadKanban;
